"use client"

import { useState, useEffect } from "react"
import { usePathname } from "next/navigation"
import Link from "next/link"
import { Menu, X, Moon, Sun } from "lucide-react"
import { Button } from "@/components/ui/button"
import FlowingMenu from "@/components/FlowingMenu"

export default function Sidebar() {
  const [isSidebarOpen, setIsSidebarOpen] = useState(false)
  const [isDarkMode, setIsDarkMode] = useState(false)
  const pathname = usePathname()

  useEffect(() => {
    const theme = localStorage.getItem("theme")
    if (theme === "dark") {
      setIsDarkMode(true)
      document.documentElement.classList.add("dark")
    }
  }, [])

  const toggleDarkMode = () => {
    setIsDarkMode(!isDarkMode)
    if (!isDarkMode) {
      document.documentElement.classList.add("dark")
      localStorage.setItem("theme", "dark")
    } else {
      document.documentElement.classList.remove("dark")
      localStorage.setItem("theme", "light")
    }
  }

  const navigationItems = [
    { id: "/", text: "Home", image: "/Hall of fame/imag1.jpeg" },
    { id: "/education", text: "Education Qualifications", image: "/Hall of fame/imag2.jpeg" },
    { id: "/associations", text: "Professional Associations", image: "/Hall of fame/imag3.jpeg" },
    { id: "/teaching", text: "Teaching Experience", image: "/Hall of fame/imag4.jpeg" },
    { id: "/awards", text: "Awards", image: "/Hall of fame/imag5.jpeg" },
    { id: "/research", text: "Research and Patents", image: "/Hall of fame/imag6.jpeg" },
    { id: "/honors", text: "Honors", image: "/Hall of fame/imag7.jpeg" },
    { id: "/papers", text: "Important Papers", image: "/Hall of fame/imag8.jpeg" },
    { id: "/professional-experience", text: "Professional Experience", image: "/Hall of fame/imag9.jpeg" },
    { id: "/spirituality", text: "Spirituality", image: "/Hall of fame/imag10.jpeg" },
    { id: "/media", text: "Press and Media Appearances", image: "/Hall of fame/imag11.jpeg" },
    { id: "/hall-of-fame", text: "Famous Personalities", image: "/Hall of fame/imag12.jpeg" },
    { id: "/community-outreach", text: "Community Outreach", image: "/Hall of fame/imag13.jpeg" },
    { id: "/contact", text: "Contact", image: "/Hall of fame/imag14.jpeg" },
  ]

  return (
    <>
      {/* Mobile Menu Button */}
      <Button
        variant="ghost"
        size="icon"
        className="fixed top-4 left-4 z-50 lg:hidden"
        onClick={() => setIsSidebarOpen(!isSidebarOpen)}
      >
        {isSidebarOpen ? <X className="h-6 w-6" /> : <Menu className="h-6 w-6" />}
      </Button>

      {/* Sidebar */}
      <aside
        className={`fixed top-0 left-0 h-full w-80 bg-sidebar border-r border-sidebar-border transition-transform duration-300 z-40 ${
          isSidebarOpen ? "translate-x-0" : "-translate-x-full"
        } lg:translate-x-0 overflow-hidden`}
      >
        <div className="p-6 flex flex-col h-full">
          {/* Header */}
          <div className="mb-6">
            <h1 className="text-xl font-bold mb-1 text-sidebar-foreground text-balance">Dr. Madhura Yadav</h1>
            <p className="text-sm text-muted-foreground">Portfolio</p>
          </div>

          {/* Flowing Navigation */}
          <nav className="flex-1">
            <div style={{ height: '900px', position: 'relative' }}>
              <FlowingMenu 
                items={navigationItems}
                speed={25}
                textColor="#ffffff"
                bgColor="#2a2a2a"
                marqueeBgColor="#f0f0f0"
                marqueeTextColor="#2a2a2a"
                borderColor="#666666"
                onItemClick={() => setIsSidebarOpen(false)}
              />
            </div>
          </nav>

          {/* Dark Mode Toggle */}
          <div className="mt-auto pt-4 border-t border-sidebar-border space-y-4">
            <Button
              variant="outline"
              size="sm"
              onClick={toggleDarkMode}
              className="w-full justify-start gap-2 bg-transparent"
            >
              {isDarkMode ? (
                <>
                  <Sun className="h-4 w-4" />
                  Light Mode
                </>
              ) : (
                <>
                  <Moon className="h-4 w-4" />
                  Dark Mode
                </>
              )}
            </Button>
            <p className="text-xs text-muted-foreground">© 2025 Dr. Madhura Yadav</p>
          </div>
        </div>
      </aside>

      {/* Mobile Sidebar Overlay */}
      {isSidebarOpen && (
        <div className="fixed inset-0 bg-black/50 z-30 lg:hidden" onClick={() => setIsSidebarOpen(false)} />
      )}
    </>
  )
}
